"""Build standalone demos. No runtime dependency on this module."""
from pathlib import Path
from html import escape
import json
ROOT = Path(__file__).resolve().parents[1]
CSS = '''
:root{--ink:#172c37;--muted:#526873;--bg:#eef3f5;--paper:#fff;--accent:#006d77;--pale:#def2ef;--line:#c8d7dd;--gold:#90621a}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 'Segoe UI',Arial,sans-serif}a{color:var(--accent);text-underline-offset:4px}button,input,select,textarea{font:inherit}button,.button{cursor:pointer;background:var(--accent);color:white;border:1px solid var(--accent);padding:10px 17px;border-radius:8px;text-decoration:none;display:inline-block;font-weight:650}button:hover,.button:hover{filter:brightness(.92)}button.secondary{background:var(--paper);color:var(--accent)}button:disabled{opacity:.5;cursor:default}button[aria-pressed=true],.selected{outline:3px solid var(--gold);outline-offset:2px}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,summary:focus-visible{outline:3px solid #b16b09;outline-offset:3px}input,select,textarea{background:white;color:var(--ink);border:1px solid #8fa7b3;padding:10px;border-radius:7px;max-width:100%}input[type=number]{width:100%}label{display:block;font-weight:600;margin:10px 0}label input,label select,label textarea{display:block;margin-top:5px}header{background:#123b48;color:white;padding:18px max(5vw,20px);display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap}header a{color:#c4ece6}header strong{font:700 19px Georgia,serif}nav{display:flex;gap:18px;flex-wrap:wrap}main{max-width:1160px;margin:auto;padding:30px 24px 70px}.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:1.8px;color:var(--accent);font-weight:750}h1,h2,h3{line-height:1.2}h1{font:normal clamp(33px,5vw,56px)/1.12 Georgia,serif;margin:12px 0 18px;max-width:900px}h2{font:normal 29px Georgia,serif;margin:0 0 18px}h3{font-size:18px}p{max-width:78ch}.lead{font-size:18px;color:var(--muted);max-width:760px}.workspace{margin-top:28px;border:1px solid var(--line);border-radius:15px;background:var(--paper);padding:clamp(18px,3vw,34px);box-shadow:0 12px 35px #1634420a}.row{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.split{display:grid;grid-template-columns:minmax(220px,1fr) minmax(280px,1.65fr);gap:28px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px}.card{border:1px solid var(--line);padding:18px;border-radius:10px;background:var(--paper)}.card h3{margin-top:0}.muted,small{color:var(--muted)}.tag{display:inline-block;padding:3px 10px;border:1px solid var(--line);border-radius:30px;font-size:12px;font-weight:700;color:var(--accent);background:var(--pale)}.notice,.feedback{padding:15px 18px;border-left:4px solid var(--accent);background:var(--pale);margin:18px 0;border-radius:0 8px 8px 0}.feedback:empty{display:none}.error{border-color:#a93333;background:#fff0ec}.metric{font:normal 38px Georgia,serif;color:var(--accent)}.choices{display:grid;gap:10px;margin:18px 0}.choices button{text-align:left;background:#f1f7f8;color:var(--ink);border-color:var(--line)}.choices button:hover{background:var(--pale)}.progress{height:8px;background:#e1e9ec;border-radius:8px;overflow:hidden;margin:15px 0}.progress span{display:block;background:var(--accent);height:100%}table{width:100%;border-collapse:collapse}th,td{text-align:left;border-bottom:1px solid var(--line);padding:10px}caption{text-align:left;font-weight:700;margin:10px 0}details{border-top:1px solid var(--line);padding:16px 0}summary{cursor:pointer;font-weight:700;color:var(--accent)}.guide{margin-top:42px}.guide .grid{margin-top:20px}.guide li{margin:8px 0}.source{font-size:13px;margin-top:20px}.arabic{font:32px/1.8 'Traditional Arabic','Segoe UI',serif;direction:rtl}svg{max-width:100%;height:auto}footer{border-top:1px solid var(--line);margin-top:35px;padding-top:18px;font-size:13px;color:var(--muted)}[hidden]{display:none!important}@media(max-width:700px){main{padding:24px 16px 50px}.split{grid-template-columns:1fr}header{padding:16px}nav{gap:12px;font-size:14px}th,td{padding:7px;font-size:14px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{animation:none!important;transition:none!important}}
'''
JS = '''const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const store={get(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{return false}}};'''
def build(slug,title,category,description,body,script,*,next_steps,build_steps,stack,data,watchout,sources=(),css='',hosting=None):
    """All arguments after script are mandatory app-specific production guidance."""
    def lis(items): return '<ul>'+''.join('<li>'+x+'</li>' for x in items)+'</ul>'
    refs=''.join(f'<li><a href="{escape(url,quote=True)}" target="_blank" rel="noopener noreferrer">{escape(label)}</a></li>' for label,url in sources)
    host = hosting or 'Publish this HTML on Cloudflare Pages. Static requests are free and unlimited under the current plan. Keep content in cacheable files. Add a Worker and D1 only for shared accounts or writes.'
    html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{escape(description,quote=True)}"><title>{escape(title)} | Islamic Product Lab</title><style>{CSS}\n{css}</style></head><body><header><strong>Islamic Product Lab</strong><nav aria-label="Main"><a href="index.html">All 27 demos</a><a href="#demo">Try the demo</a><a href="#build">Build this app</a><a href="islamic_product_atlas.html">Original atlas</a></nav></header><main><div class="eyebrow">{escape(category)} · working prototype</div><h1>{escape(title)}</h1><p class="lead">{escape(description)}</p><section class="workspace" id="demo" aria-label="Interactive demo">{body}</section><section class="guide" id="build"><div class="eyebrow">From prototype to product</div><h2>Build this app</h2><p>{watchout}</p><div class="grid"><article class="card"><h3>What to add next</h3>{lis(next_steps)}</article><article class="card"><h3>Recommended stack</h3>{lis(stack)}</article></div><details open><summary>Implementation steps</summary><ol>{''.join('<li>'+x+'</li>' for x in build_steps)}</ol><h3>Data model and content</h3><p>{data}</p></details><details open><summary>Low-cost deployment and scale</summary><p>{host}</p><p>For optional APIs, Workers Free currently allows 100,000 requests per day across the account. Workers Paid starts at US$5/month. D1 has separate usage limits. Domain, editorial review, email, and third-party data costs are additional.</p><p>Capacity depends on requests and database work, not registered users. For example, 10,000 daily users making four API calls each produce 40,000 API requests. Load-test the actual workflow. Cache public reads, index database queries, and limit writes.</p><p class="source">Hosting facts checked 16 October 2026. <a href="https://developers.cloudflare.com/pages/functions/pricing/">Pages pricing</a> · <a href="https://www.cloudflare.com/plans/developer-platform/">Workers plans</a> · <a href="https://developers.cloudflare.com/d1/platform/pricing/">D1 pricing</a>. Recheck before launch.</p></details><details><summary>Sources and review</summary><ul>{refs}</ul><p>Demo explanations are paraphrases unless marked as quotations. Review content, source editions, translation rights, and accessibility before public release.</p></details></section><footer>Standalone local demo · no external libraries or network calls required for the interaction · technical guide uses STE-guided language</footer></main><script>'use strict';{JS}\n{script}\n</script></body></html>'''
    html=html.replace('href="islamic_product_atlas.html"','href="_reference/atlas.html"')
    (ROOT/(slug+'.html')).write_text(html,encoding='utf-8')
    return ROOT/(slug+'.html')
